package com.exptech.dpip.widget

import org.junit.Assert.assertEquals
import org.junit.Assert.assertNotNull
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Test
import java.io.File

/**
 * The generated township resources, and the resolver built on them.
 *
 * Two things are worth testing and they need different inputs: that the **real**
 * generated bytes decode (a format the generator and this decoder must agree
 * on), and that the **rules** — polygon containment, holes, the uncertainty
 * circle, the bounded fallback and a code-set mismatch — behave. The second is
 * tested on a synthesized table so it does not depend on where the boundaries of
 * a real Taiwanese village happen to fall.
 */
class WidgetTownshipResourcesTest {
    private fun asset(name: String): File {
        for (candidate in listOf("src/main/assets/$name", "app/src/main/assets/$name")) {
            val file = File(candidate)
            if (file.isFile) return file
        }
        error("generated asset $name not found; run python3 tool/gen/widget_township_resources.py")
    }

    private fun fix(
        latitude: Double,
        longitude: Double,
        accuracyMeters: Double = 50.0,
    ) = WidgetFix(
        latitude = latitude,
        longitude = longitude,
        accuracyMeters = accuracyMeters,
        ageMilliseconds = 1_000,
    )

    @Test
    fun `the generated directory and boundaries decode and agree`() {
        val directory = TownshipDirectory.decode(
            asset("widget_township_directory.json").readText(Charsets.UTF_8),
        )
        val boundaries = TownshipBoundaryTable.decode(
            asset("widget_township_boundaries.bin").readBytes(),
        )
        checkNotNull(directory)
        checkNotNull(boundaries)

        // Every Taiwanese township: a truncated or half-written pair would show
        // up here as a small number.
        assertTrue(directory.regionCodes.size > 300)
        assertEquals(directory.regionCodes, boundaries.regionCodes)
        checkNotNull(WidgetTownshipResolver.of(boundaries, directory))
    }

    @Test
    fun `a real Taipei coordinate resolves to the township that contains it`() {
        val resolver = realResolver()
        val resolved = resolver.resolve(fix(25.032188, 121.5183226))
        checkNotNull(resolved)
        assertEquals(WidgetAddress.CurrentLocation, resolved.address)
        assertTrue(isValidRegionCode(resolved.regionCode))

        // Whatever code won, it must be the township the point is actually in —
        // not one the nearest-centroid rule happened to pick from far away.
        val township = resolver.township(resolved.regionCode)
        checkNotNull(township)
        assertTrue(Math.abs(township.latitude - 25.032188) < 0.05)
        assertTrue(Math.abs(township.longitude - 121.5183226) < 0.05)
    }

    @Test
    fun `a point in another country does not resolve to a Taiwan township`() {
        val resolver = realResolver()
        // Tokyo and Sydney. The nearest-centroid fallback must not name a
        // Taiwanese village for them — an old observation plus a notice is the
        // honest screen.
        assertNull(resolver.resolve(fix(35.6812, 139.7671)))
        assertNull(resolver.resolve(fix(-33.86, 151.21)))
    }

    @Test
    fun `a fix whose uncertainty reaches a boundary claims neither township`() {
        val resolver = synthesizedResolver()
        // Township 100 spans longitude 0..0.2°. At 0.198 the centre is inside and
        // about 222 m from the edge, so a 400 m accuracy reaches past it.
        assertNull(resolver.resolve(fix(0.1, 0.198, accuracyMeters = 400.0)))
        // The same point with a 50 m fix is comfortably inside.
        assertEquals("100", resolver.resolve(fix(0.1, 0.198, accuracyMeters = 50.0))?.regionCode)
    }

    @Test
    fun `a boundary between two sample directions is still found`() {
        val resolver = synthesizedResolver()
        // The counterexample a sampled circle misses: a boundary 461.94 m away
        // whose normal sits 22.5° between two of eight sample directions projects
        // onto them just inside the edge, so a 500 m fix looks entirely within
        // the township. The distance test sees the 461.94 m.
        val metresPerDegree = WidgetTownshipResolver.metresPerDegree
        val offset = 461.94 / metresPerDegree
        assertNull(
            resolver.resolve(fix(0.1, 0.2 - offset, accuracyMeters = 500.0)),
        )
        // Just accurate enough to be sure which side it is on.
        assertEquals(
            "100",
            resolver.resolve(fix(0.1, 0.2 - offset, accuracyMeters = 400.0))?.regionCode,
        )
    }

    @Test
    fun `a fix close to a hole cannot claim the township either`() {
        val resolver = synthesizedResolver()
        // Township 100's hole spans 0.08..0.12. A point at 0.126 is inside the
        // township but 667 m from the hole's edge; a 1 km fix could belong to
        // whatever the hole is.
        assertNull(resolver.resolve(fix(0.1, 0.126, accuracyMeters = 1_000.0)))
        assertEquals("100", resolver.resolve(fix(0.1, 0.126, accuracyMeters = 50.0))?.regionCode)
    }

    @Test
    fun `a coarse fix near the coast degrades instead of picking a side`() {
        val resolver = synthesizedResolver()
        // Just inside the western edge at longitude 0: a 400 m accuracy reaches
        // past it.
        assertNull(resolver.resolve(fix(0.1, 0.0002, accuracyMeters = 400.0)))
    }

    @Test
    fun `a fix outside every polygon resolves to nothing`() {
        val resolver = synthesizedResolver()
        // A short way west of the township and entirely outside it. The nearest
        // centroid is 0.105° away — well inside the bound the previous version
        // used — and it is still not a township: naming one would claim a town
        // the fix has no evidence for.
        assertNull(resolver.resolve(fix(0.1, -0.005, accuracyMeters = 50.0)))
    }

    @Test
    fun `a city in another country is not given a Taiwanese township`() {
        // Xiamen, against the **real** generated resources: 24.4798, 118.0894 is
        // 0.1499° from Lieyu's centroid (894), which a 0.5° centroid fallback
        // accepted. A widget in Fujian must not say 烈嶼.
        val resolver = realResolver()
        assertNull(resolver.resolve(fix(24.4798, 118.0894, accuracyMeters = 50.0)))
        // …and the neighbouring Taiwanese island it is closest to still resolves,
        // so this is the fallback being removed, not the polygons being wrong.
        assertEquals("894", resolver.resolve(fix(24.4294, 118.2444, accuracyMeters = 50.0))?.regionCode)
    }

    @Test
    fun `the distance to a boundary is measured in metres, segment by segment`() {
        val boundaries = TownshipBoundaryTable.decode(squareBoundaries())!!
        // 0.001° of latitude is 111.32 m.
        val metresPerDegree = WidgetTownshipResolver.metresPerDegree
        // Close to the southern edge and well clear of the hole: 0.02° of
        // latitude.
        assertEquals(0.02 * metresPerDegree, boundaries.minimumDistanceMeters(0.02, 0.1), 5.0)

        // The hole counts as a boundary: at 0.05° latitude the nearest ring is
        // the hole's southern edge at 0.08°, not the township's own edge.
        assertEquals(0.03 * metresPerDegree, boundaries.minimumDistanceMeters(0.05, 0.1), 5.0)

        // Outside the township entirely, 0.001° west of its edge.
        assertEquals(0.001 * metresPerDegree, boundaries.minimumDistanceMeters(0.1, -0.001), 5.0)
    }

    @Test
    fun `a mismatched directory and boundary set is refused`() {
        val boundaries = TownshipBoundaryTable.decode(squareBoundaries())!!
        val directory = TownshipDirectory.of(
            listOf(WidgetTownship("999", "別處", "別縣", 1.0, 1.0)),
        )!!
        assertNull(WidgetTownshipResolver.of(boundaries, directory))
    }

    @Test
    fun `ray casting honours the outer ring and its holes`() {
        val boundaries = TownshipBoundaryTable.decode(squareBoundaries())!!

        // codeAt(latitude, longitude): township 100 spans both axes 0..0.2, and
        // township 200 spans longitude 0.22..0.42 at the same latitude band.
        assertEquals("100", boundaries.codeAt(0.05, 0.1))
        assertEquals("200", boundaries.codeAt(0.1, 0.3))
        // Inside the outer ring but inside its hole: not part of the township.
        assertNull(boundaries.codeAt(0.1, 0.1))
        // Outside every ring.
        assertNull(boundaries.codeAt(0.1, 0.6))
        assertNull(boundaries.codeAt(-0.1, 0.1))
    }

    @Test
    fun `a boundary payload with trailing bytes is refused`() {
        val valid = squareBoundaries()
        assertNotNull(TownshipBoundaryTable.decode(valid))
        assertNull(TownshipBoundaryTable.decode(valid + byteArrayOf(0)))
    }

    @Test
    fun `a truncated boundary payload is refused`() {
        val valid = squareBoundaries()
        assertNull(TownshipBoundaryTable.decode(valid.copyOf(valid.size / 2)))
        assertNull(TownshipBoundaryTable.decode(ByteArray(0)))
    }

    @Test
    fun `a directory with a duplicated code is refused`() {
        assertNull(
            TownshipDirectory.of(
                listOf(
                    WidgetTownship("100", "甲", "縣", 1.0, 1.0),
                    WidgetTownship("100", "乙", "縣", 2.0, 2.0),
                ),
            ),
        )
        assertNull(TownshipDirectory.of(emptyList()))
    }

    private fun realResolver(): WidgetTownshipResolver {
        val directory = TownshipDirectory.decode(
            asset("widget_township_directory.json").readText(Charsets.UTF_8),
        )
        val boundaries = TownshipBoundaryTable.decode(
            asset("widget_township_boundaries.bin").readBytes(),
        )
        return checkNotNull(
            WidgetTownshipResolver.of(checkNotNull(boundaries), checkNotNull(directory)),
        )
    }

    private fun synthesizedResolver(): WidgetTownshipResolver {
        val boundaries = TownshipBoundaryTable.decode(squareBoundaries())!!
        val directory = TownshipDirectory.of(
            listOf(
                WidgetTownship("100", "甲", "縣", 0.1, 0.1),
                WidgetTownship("200", "乙", "縣", 0.1, 0.32),
            ),
        )!!
        return checkNotNull(WidgetTownshipResolver.of(boundaries, directory))
    }

    // ── A two-township table, one of them with a hole ───────────────────────
    //
    // Coordinates are the wire's 1/10 000 of a degree, so 2 000 units is 0.2°.
    // Township 100 spans longitude 0..0.2 and latitude 0..0.2 with a square hole
    // at 0.08..0.12; township 200 spans longitude 0.22..0.42 over the same
    // latitude band. Both are far smaller than the 0.5° fallback radius, so the
    // "outside everything" case is reachable in a test.

    private fun squareBoundaries(): ByteArray {
        val writer = BoundaryWriter()
        writer.count(2)

        writer.count(3)
        writer.ascii("100")
        writer.count(1)
        writer.count(2)
        writer.ring(listOf(0 to 0, 2_000 to 0, 2_000 to 2_000, 0 to 2_000))
        writer.ring(listOf(800 to 800, 1_200 to 800, 1_200 to 1_200, 800 to 1_200))

        writer.count(3)
        writer.ascii("200")
        writer.count(1)
        writer.count(1)
        writer.ring(listOf(2_200 to 0, 4_200 to 0, 4_200 to 2_000, 2_200 to 2_000))

        return writer.toByteArray()
    }

    private class BoundaryWriter {
        private val bytes = ArrayList<Byte>()

        fun count(value: Int) = varint(value.toLong())

        fun ascii(value: String) {
            for (character in value) bytes.add(character.code.toByte())
        }

        /** One ring, emitted as cumulative zigzag deltas, longitude first. */
        fun ring(points: List<Pair<Int, Int>>) {
            count(points.size)
            var previousLongitude = 0
            var previousLatitude = 0
            for ((longitude, latitude) in points) {
                zigzag(longitude - previousLongitude)
                zigzag(latitude - previousLatitude)
                previousLongitude = longitude
                previousLatitude = latitude
            }
        }

        fun toByteArray(): ByteArray = bytes.toByteArray()

        private fun varint(value: Long) {
            var remaining = value
            while (true) {
                val payload = (remaining and 0x7F).toInt()
                remaining = remaining ushr 7
                if (remaining == 0L) {
                    bytes.add(payload.toByte())
                    return
                }
                bytes.add((payload or 0x80).toByte())
            }
        }

        private fun zigzag(value: Int) {
            val encoded = ((value shl 1) xor (value shr 31)).toLong() and 0xFFFF_FFFFL
            varint(encoded)
        }
    }
}
